INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65256504', 65256504, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Dokumen Analisis Semantik Narasi Pengendalian Triwulanan untuk Optimalisasi Manajemen Risiko Pembangunan Nasional', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99974400, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Keluaran yang diharapkan dari kegiatan ini adalah: 1) Draf instrumen analisis semantik Executive Summary; serta 2) Draf pedoman bahasa dan glosarium istilah kebijakan. Adapun rincian keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut: Periode Keluaran Per Termin Termin 1 Analisis awal dokumen evaluasi tahun sebelumnya untuk pemetaan istilah dan pola narasi kebijakan. Penyusunan draf awal instrumen analisis semantik Executive Summary. Termin 2 Analisis keselarasan narasi pengendalian TW I dengan dokumen perencanaan. Identifikasi potensi risiko semantik dalam pelaporan TW I. Termin 3 Penyusunan rangkuman evaluasi TW I berbasis kejelasan bahasa kebijakan. Penyusunan draf pedoman bahasa dan SOP narasi pengendalian triwulanan. Termin 4 Analisis konsistensi narasi pengendalian TW II terhadap dokumen perencanaan. Identifikasi pergeseran makna dan bias narasi pelaporan TW II. Termin 5 Penyusunan rangkuman evaluasi TW II dan penajaman bahasa Executive Summary. Analisis konsistensi narasi pengendalian TW III terhadap dokumen perencanaan. Termin 6 Identifikasi risiko semantik dalam pelaporan TW III. Penyusunan rangkuman evaluasi TW III dan refleksi kualitas bahasa kebijakan tahunan.', 'Lingkup tugas dan tanggung jawab Jasa Konsultan Junior Penyusunan Dokumen Analisis Semantik Narasi Pengendalian Triwulanan untuk Optimalisasi Manajemen Risiko Pembangunan Nasional adalah sebagai berikut: 1) Melakukan analisis awal terhadap dokumen evaluasi dan pengendalian tahun sebelumnya untuk memetakan istilah kunci, isu semantik, dan pola narasi kebijakan sebagai dasar penyusunan instrumen analisis semantik. 2) Menyusun dan mengembangkan draf instrumen analisis semantik yang digunakan untuk penelaahan bahasa dan struktur Executive Summary laporan pengendalian dan evaluasi. 3) Melakukan analisis keselarasan narasi pengendalian triwulanan dengan dokumen perencanaan pembangunan nasional, khususnya pada Prioritas Nasional 3 dan Prioritas Nasional 5. 4) Mengidentifikasi potensi risiko semantik, pergeseran makna, dan bias narasi dalam laporan pengendalian triwulanan sebagai bagian dari dukungan manajemen risiko pembangunan nasional. 5) Menyusun rangkuman dan penyempurnaan bahasa laporan evaluasi triwulanan, termasuk penajaman struktur informasi dan kejelasan narasi Executive Summary. 6) Menyusun draf pedoman bahasa dan SOP narasi pengendalian triwulanan, termasuk perumusan glosarium istilah kebijakan untuk menjamin konsistensi terminologi lintas dokumen. 7) Melakukan proses quality assurance aspek bahasa dan penyajian terhadap dokumen hasil pengendalian dan evaluasi kebijakan strategis III. 8) Menyusun laporan hasil kegiatan bulanan sesuai dengan termin waktu dan format yang ditetapkan, sebagai bentuk pertanggungjawaban pelaksanaan pekerjaan. 9) Melaksanakan koordinasi teknis terbatas dengan tim substansi dan administrasi, khususnya untuk sinkronisasi hasil analisis bahasa dan penyempurnaan dokumen. 10) Melaksanakan tugas lain yang diberikan oleh pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2039763);
